(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*20 + Math.cos(y*0.013-t*0.22)*14;
  const w1y = Math.cos(y*0.02-t*0.28)*18 + Math.sin(x*0.016+t*0.32)*12;
  const w2x = Math.sin((x+w1x)*0.025-t*0.15)*10 + Math.cos((y+w1y)*0.02+t*0.18)*8;
  const w2y = Math.cos((y+w1y)*0.022+t*0.17)*10 + Math.sin((x+w1x)*0.019-t*0.2)*8;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.85],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*110, 40+Math.cos(t*0.65+1)*60, 0.11, 2.1, 0.88],
    [400+Math.cos(t*0.38+2)*70, 200+Math.sin(t*0.58+4)*50, 0.065, 2.4, 1.12]
  ];
  let aS=0, iS=0, cross=0;
  for (let j=0; j<src.length; j++) {
    const [sX,sY,f,sp,w] = src[j];
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const a = Math.sin(d*f-t*sp);
    const b = Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS += a*w; iS += b*w;
    for (let k=j+1; k<src.length; k++) {
      const [sX2,sY2,f2,sp2,w2] = src[k];
      const d2 = Math.sqrt((sx-sX2)**2+(sy-sY2)**2);
      cross += Math.sin(d*f-t*sp)*Math.sin(d2*f2-t*sp2)*0.15*w*w2;
    }
  }
  aS/=8; iS/=8;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.065+Math.cos(sy*0.05+t)*3+t*1.3)*0.15
    + Math.sin(Math.cos(sx*0.04-t*0.5)*4+sy*0.055+t*0.9)*0.15;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
