    + Math.sin(dist*0.08-ang*5+t*2)*0.15 + Math.sin(dist*0.03+ang*2-t*0.8)*0.15;
  const lap = (aS+iS)*0.5 - aS*iS*0.3 + cross*0.5;
  const reaction = Math.tanh((aS-iS*0.7+bg*0.3+spiral+lap)*2.2);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.08-sy*0.12+t*0.7)*0.3)*1.5)*0.3;
  const micro = Math.sin(sx*0.3+sy*0.2+t*3)*Math.sin(sx*0.2-sy*0.25-t*2.5)*0.08;
  const blend = reaction*0.65+cell*0.25+micro*0.1, v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[12,45,85],[18,95,120],[25,155,145],[140,190,130],
    [220,200,65],[215,140,60],[185,75,65],[120,35,65],[50,15,55],[6,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const sm = f*f*(3-2*f);
