  const edge = Math.abs(reaction)>0.65?1.0+Math.abs(reaction)*0.18:1.0;
  const vig = 1.0-Math.sqrt((x-cx)**2+(y-cy)**2)/420*0.15;
  const glow = Math.max(0, 1-Math.abs(reaction)*1.8)*0.12;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*sm)*lum*edge*vig+glow*40)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*sm)*lum*edge*vig+glow*60)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*sm)*lum*edge*vig+glow*80)|0)
  ];
}
